t.script:
document.addEventListener('DOMContentLoaded', function() {
    const pickupDate = document.getElementById('pickup_date');
    const returnDate = document.getElementById('return_date');
    const calculator = document.getElementById('priceCalculator');
    const dailyRate = ;

    function calculatePrice() {
        if (pickupDate.value && returnDate.value) {
            const start = new Date(pickupDate.value);
            const end = new Date(returnDate.value);
            const days = Math.ceil((end - start) / (1000 * 60 * 60 * 24));

            if (days > 0) {
                calculator.classList.remove('d-none');
                document.getElementById('calcDays').textContent = days;
                document.getElementById('calcTotal').textContent = (dailyRate * days).toFixed(2);
            } else {
                calculator.classList.add('d-none');
            }
        }
    }

    pickupDate.addEventListener('change', calculatePrice);
    returnDate.addEventListener('change', calculatePrice);
    calculatePrice();
});

document.addEventListener('DOMContentLoaded', function() {
    const dailyRate = ;
    const pickupDate = document.getElementById('booking_pickup_date');
    const returnDate = document.getElementById('booking_return_date');

    function updateSummary() {
        let days = 0;
        if (pickupDate.value && returnDate.value) {
            const start = new Date(pickupDate.value);
            const end = new Date(returnDate.value);
            days = Math.ceil((end - start) / (1000 * 60 * 60 * 24));
            if (days < 1) days = 0;
        }

        document.getElementById('summaryDays').textContent = days || '-';

        let subtotal = dailyRate * days;
        let extras = 0;

        // Calculate extras
        if (document.getElementById('extraInsurance').checked) extras += 15 * days;
        if (document.getElementById('extraGps').checked) extras += 5 * days;
        if (document.getElementById('extraChildSeat').checked) extras += 8 * days;
        if (document.getElementById('extraDriver').checked) extras += 10 * days;

        document.getElementById('summarySubtotal').textContent = '$' + subtotal.toFixed(2);

        let extrasHtml = '';
        if (extras > 0) {
            extrasHtml = '<div class="d-flex justify-content-between mb-2"><span>Extras:</span><span>$' + extras.toFixed(2) + '</span></div>';
        }
        document.getElementById('summaryExtras').innerHTML = extrasHtml;

        const total = subtotal + extras;
        document.getElementById('summaryTotal').textContent = '$' + total.toFixed(2);
    }

    pickupDate.addEventListener('change', updateSummary);
    returnDate.addEventListener('change', updateSummary);
    document.querySelectorAll('input[type="checkbox"]').forEach(function(cb) {
        cb.addEventListener('change', updateSummary);
    });

    updateSummary();
});
